 look(){const c=this.view.camera,d=new T.Vector3(-Math.sin(this.yaw)*Math.cos(this.pitch),Math.sin(this.pitch),-Math.cos(this.yaw)*Math.cos(this.pitch));this.view.controls.target.copy(c.position).add(d);c.lookAt(this.view.controls.target);}
